From d0224efcab36de8f47805fe435b8102b4c511b75 Mon Sep 17 00:00:00 2001
From: JKAUSHALYA <jayangak@wso2.com>
Date: Fri, 9 Mar 2018 13:01:45 +0530
Subject: [PATCH 1/2] Fix the path name issue in Windows

Windows path names cannot have ":" in it. So this will change the date time in path name to a timestamp.
---
 .../wso2/carbon/privacy/forgetme/ForgetMeExecutionEngine.java | 4 +---
 1 file changed, 1 insertion(+), 3 deletions(-)

diff --git a/components/org.wso2.carbon.privacy.forgetme.tool/src/main/java/org/wso2/carbon/privacy/forgetme/ForgetMeExecutionEngine.java b/components/org.wso2.carbon.privacy.forgetme.tool/src/main/java/org/wso2/carbon/privacy/forgetme/ForgetMeExecutionEngine.java
index bd24dcc..270ebb0 100644
--- a/components/org.wso2.carbon.privacy.forgetme.tool/src/main/java/org/wso2/carbon/privacy/forgetme/ForgetMeExecutionEngine.java
+++ b/components/org.wso2.carbon.privacy.forgetme.tool/src/main/java/org/wso2/carbon/privacy/forgetme/ForgetMeExecutionEngine.java
@@ -221,9 +221,7 @@ public ForgetMeResult call() throws InstructionExecutionException {
         }

         private String getReportFileName() {
-
-            SimpleDateFormat simpleDateFormat = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm'Z'");
-            return "Report-" + name + "-" + simpleDateFormat.format(new Date()) + ".txt";
+            return "Report-" + name + "-" + System.currentTimeMillis() + ".txt";
         }
     }
 }

From 9ed5f6d0214fe1d5ad0cd156a4e9e82f057da45d Mon Sep 17 00:00:00 2001
From: JKAUSHALYA <jayangak@wso2.com>
Date: Mon, 12 Mar 2018 19:25:20 +0530
Subject: [PATCH 2/2] Update the regex to capture all instances of wso2carbon
 and audit logs

Fix: https://github.com/wso2/product-is/issues/2843
---
 .../resources/products/identity/conf/config-identity.json    | 2 +-
 .../forgetme/sql/instructions/RdbmsForgetMeInstruction.java  | 2 +-
 .../java/org/wso2/carbon/privacy/forgetme/ConfigReader.java  | 5 ++---
 3 files changed, 4 insertions(+), 5 deletions(-)

diff --git a/components/org.wso2.carbon.privacy.forgetme.conf/src/main/resources/products/identity/conf/config-identity.json b/components/org.wso2.carbon.privacy.forgetme.conf/src/main/resources/products/identity/conf/config-identity.json
index 7581eef..8207ec0 100644
--- a/components/org.wso2.carbon.privacy.forgetme.conf/src/main/resources/products/identity/conf/config-identity.json
+++ b/components/org.wso2.carbon.privacy.forgetme.conf/src/main/resources/products/identity/conf/config-identity.json
@@ -8,7 +8,7 @@
       "type": "log-file",
       "processor" : "log-file",
       "log-file-path" : "repository/logs",
-      "log-file-name-regex" : "wso2carbon.log"
+      "log-file-name-regex" : "^(wso2carbon(.)*\\.log|audit(.)*\\.log)$"
     },
     {
       "dir": "sql",
diff --git a/components/org.wso2.carbon.privacy.forgetme.sql/src/main/java/org/wso2/carbon/privacy/forgetme/sql/instructions/RdbmsForgetMeInstruction.java b/components/org.wso2.carbon.privacy.forgetme.sql/src/main/java/org/wso2/carbon/privacy/forgetme/sql/instructions/RdbmsForgetMeInstruction.java
index c9681ea..163050b 100644
--- a/components/org.wso2.carbon.privacy.forgetme.sql/src/main/java/org/wso2/carbon/privacy/forgetme/sql/instructions/RdbmsForgetMeInstruction.java
+++ b/components/org.wso2.carbon.privacy.forgetme.sql/src/main/java/org/wso2/carbon/privacy/forgetme/sql/instructions/RdbmsForgetMeInstruction.java
@@ -143,7 +143,7 @@ public ForgetMeResult execute(UserIdentifier userIdentifier, ProcessorConfig pro
         }

         reportAppender.appendSection("Completed all SQLs in directory %s", sqlDir);
-        log.info("Completed all SQLa in directory {}.", sqlDir);
+        log.info("Completed all SQLs in directory {}.", sqlDir);
         return new ForgetMeResult();
     }

diff --git a/components/org.wso2.carbon.privacy.forgetme.tool/src/main/java/org/wso2/carbon/privacy/forgetme/ConfigReader.java b/components/org.wso2.carbon.privacy.forgetme.tool/src/main/java/org/wso2/carbon/privacy/forgetme/ConfigReader.java
index 6d66ca8..3ee2c10 100644
--- a/components/org.wso2.carbon.privacy.forgetme.tool/src/main/java/org/wso2/carbon/privacy/forgetme/ConfigReader.java
+++ b/components/org.wso2.carbon.privacy.forgetme.tool/src/main/java/org/wso2/carbon/privacy/forgetme/ConfigReader.java
@@ -161,9 +161,8 @@ private void loadDirectories(JSONArray directories, SystemConfig systemConfig, P
     private Properties getAdditionalProperties(JSONObject dirConfig, VariableResolver variableResolver) {

         Properties properties = new Properties();
-        dirConfig.forEach((key, value) -> {
-            properties.setProperty(key.toString(), variableResolver.resolve(value.toString()));
-        });
+        dirConfig.forEach((key, value) -> properties.setProperty(key.toString(),
+                variableResolver.resolve(value.toString())));
         return properties;
     }
